def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        bid = min(budget, DAILY_SALARY * 0.35)
        return float(max(0.0, bid))

    prev_bids = []
    threat_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive:
        if opp.get('budget', 0) >= budget * 0.9:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            b = prev.get('bid', 0)
            prev_bids.append(b)
            if opp.get('hp', 10) > 0:
                threat_bids.append(b)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    total_players = 1 + len(alive)
    est_winners = max(1, int(supply) // int(WATER_REQ))
    scarcity = total_players - est_winners

    if hp <= 2 or no_water >= 2:
        base = max(DAILY_SALARY * 1.05, highest_prev + 8.0)
    elif hp <= 4 or no_water >= 1:
        base = max(DAILY_SALARY * 0.88, highest_prev + 3.0)
    else:
        if scarcity >= 2:
            base = max(DAILY_SALARY * 0.72, avg_prev * 0.92)
        else:
            base = max(DAILY_SALARY * 0.46, avg_prev * 0.72)

    if urgent_opp >= est_winners:
        base += 8.0
    elif urgent_opp == 0 and scarcity <= 1:
        base -= 6.0

    if rich_opp >= 2:
        base += 4.0

    if day >= 8 and hp <= 5:
        base += 10.0

    if budget < DAILY_SALARY * 2:
        base = min(base, budget * 0.72)
    elif budget > DAILY_SALARY * 8 and hp > 5 and scarcity <= 1:
        base -= 3.0

    bid = max(1.0, min(budget, base))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
