def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opponents = {aid: o for aid, o in opponents_status.items() if o['alive']}
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents.values():
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            yesterday_bids.append(trace['bid'])

    if yesterday_bids:
        max_prev = max(yesterday_bids)
    else:
        max_prev = DAILY_SALARY * 0.5

    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    # Base bid: slightly above highest previous, but not too aggressive
    base_bid = max_prev * 1.1

    # Adjust based on desperation
    if hp <= 3 or no_water_days >= 1:
        multiplier = 1.3
    else:
        multiplier = 1.0

    target = base_bid * multiplier
    # Ensure a minimum bid to be competitive
    min_bid = DAILY_SALARY * 0.5 * multiplier
    target = max(target, min_bid)
    # Cap by budget and a safe maximum percentage of salary
    target = min(target, budget, DAILY_SALARY * 1.2)
    # Also ensure we don't bid more than needed: we can reduce if we are safe
    if hp > 5 and no_water_days == 0:
        target = min(target, DAILY_SALARY * 0.8)

    return float(target)
